import javax.servlet.*;
import javax.servlet.http.*;
import javax.xml.parsers.*;
import org.w3c.dom.*;
import org.xml.sax.InputSource;

public class InsecureLoginServlet extends HttpServlet {
    private Connection conn;

    public void init() {
        try {
            // Hardcoded credentials (also bad practice)
            conn = DriverManager.getConnection("jdbc:mysql://localhost/appdb", "user", "pass");
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String username = req.getParameter("username");
        String password = req.getParameter("password");

        // 1) SQL Injection: concatenating user input directly into query (vulnerable)
        String sql = "SELECT id FROM users WHERE username = '" + username + "' AND password = '" + password + "'";
        try (Statement st = conn.createStatement();
             ResultSet rs = st.executeQuery(sql)) {
            if (rs.next()) {
                resp.getWriter().println("Welcome!");
            } else {
                resp.getWriter().println("Invalid credentials.");
            }
        } catch (SQLException e) {
            resp.getWriter().println("Error");
        }

        // 2) Insecure XML parsing: XXE enabled by default DocumentBuilderFactory
        String xml = req.getParameter("profileXml"); // Attacker-controlled XML
