                Document doc = db.parse(new InputSource(new StringReader(xml)));
                resp.getWriter().println("Profile loaded: " + doc.getDocumentElement().getNodeName());
            } catch (Exception ex) {
                resp.getWriter().println("XML error");
            }
        }

        // 3) Insecure redirect: using unvalidated user input
        String next = req.getParameter("next");
        if (next != null) {
            // Open redirect vulnerability
            resp.sendRedirect(next);
        }
    }
}
***
/*
GOOD: Safe Java API usage with parameterized SQL, secure XML parsing, and validated redirects.
Also shows password hashing instead of plain text comparison.
*/
import java.io.*;
import java.net.URI;
import java.net.URISyntaxException;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.xml.XMLConstants;
import javax.xml.parsers.*;
import org.w3c.dom.*;
import org.xml.sax.InputSource;

public class SecureLoginServlet extends HttpServlet {
    private DataSource dataSource; // Prefer container-managed DataSource

    public void init() {
        try {
            // Example lookup; actual setup depends on your container
            javax.naming.Context ctx = new javax.naming.InitialContext();
            dataSource = (DataSource) ctx.lookup("java:comp/env/jdbc/AppDS");
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String username = req.getParameter("username");
        String password = req.getParameter("password");

        // 1) Use prepared statements to prevent SQL Injection (not vulnerable)
        String sql = "SELECT password_hash FROM users WHERE username = ?";
        try (Connection conn = dataSource.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, username);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    String storedHash = rs.getString(1);
                    if (PasswordHasher.verify(password, storedHash)) {
                        resp.getWriter().println("Welcome!");
                    } else {
                        resp.getWriter().println("Invalid credentials.");
                    }
                } else {
                    resp.getWriter().println("Invalid credentials.");
                }
            }
        } catch (SQLException e) {
            resp.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
            return;
        }

        // 2) Secure XML parsing: disable XXE and DTDs
        String xml = req.getParameter("profileXml");
        if (xml != null) {
            try {
                DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
                dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
                dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
                dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
                dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
                dbf.setExpandEntityReferences(false);
                dbf.setXIncludeAware(false);
                DocumentBuilder db = dbf.newDocumentBuilder();
                Document doc = db.parse(new InputSource(new StringReader(xml)));
                resp.getWriter().println("Profile loaded: " + doc.getDocumentElement().getNodeName());
            } catch (Exception ex) {
                resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid XML");
                return;
            }
        }

        // 3) Validate redirect targets to avoid open redirects
        String next = req.getParameter("next");
        if (next != null) {
            try {
                URI uri = new URI(next);
                // Allow only relative paths or whitelist host
                if (!uri.isAbsolute() && next.startsWith("/")) {
                    resp.sendRedirect(req.getContextPath() + next);
                } else {
                    resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid redirect");
                }
            } catch (URISyntaxException e) {
                resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid redirect");
            }
        }
    }
}

// Simple password hasher utility (e.g., using BCrypt via a library)
class PasswordHasher {
    // In production, use a well-reviewed library like BCrypt, PBKDF2, or Argon2
    static boolean verify(String password, String storedHash) {
        // Placeholder; replace with real verification
        return java.util.Objects.equals(storedHash, pseudoHash(password));
    }

    static String pseudoHash(String password) {
        // Placeholder hash to keep the snippet self-contained
        return Integer.toHexString(password.hashCode());
    }
}

