// BAD: Demonstrates improper Java API usage leading to an SQL Injection vulnerability
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class LoginServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) {
        String user = request.getParameter("username"); // user-controlled input
        String pass = request.getParameter("password"); // user-controlled input

        // vulnerable: concatenating user input directly into the SQL query enables SQL injection
        String sql = "SELECT id FROM users WHERE username = '" + user + "' AND password = '" + pass + "'";

        try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "appuser", "apppass");
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            if (rs.next()) {
                // Auth succeeded (but could be bypassed due to injection)
                response.setStatus(200);
            } else {
                response.setStatus(401);
            }
        } catch (SQLException e) {
            // Leaks internal details if printed back to user (another issue)
            e.printStackTrace();
            response.setStatus(500);
        }
    }
}
***
/*
GOOD: Fixes SQL Injection by using PreparedStatement with placeholders,
applies minimal error disclosure, and uses constant-time password checks if hashing is used.
*/
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class SafeLoginServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) {
        String user = request.getParameter("username");
        String pass = request.getParameter("password");

        // Use parameterized query to prevent SQL injection
        String sql = "SELECT id FROM users WHERE username = ? AND password = ?";

        try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "appuser", "apppass");
             PreparedStatement ps = conn.prepareStatement(sql)) {

            // Bind parameters safely; the driver will escape and type-check values
            ps.setString(1, user);
            ps.setString(2, pass); // In real apps, store and compare password hashes instead

            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    response.setStatus(200);
                } else {
                    response.setStatus(401);
                }
            }
        } catch (SQLException e) {
            // Do not leak internal details; log server-side only
            log("Database error during authentication"); // application logger
            response.setStatus(500);
        }
    }
}

