    {
      "level": "Mid-level",
      "notes": "Default weights apply. Expected independence and solid collaboration."
    },
    {
      "level": "Senior",
      "notes": "Increase emphasis on system design, cross-team impact, and mentorship. Suggested weights: System Design (+5), Mentorship (+3), Collaboration (+2), Code Quality (-3), Learning & Growth (-3)."
